        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] t = new long[n], d = new long[n], queries = new long[q];
        for (int i = 0; i < n; i++) {
